package com.spaceagent.platform.project.infrastructure.persistence;
import com.spaceagent.platform.project.domain.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.sql.*;import java.time.Instant;import java.util.*;
@Repository @ConditionalOnProperty(prefix="platform",name="persistence",havingValue="postgres") public class PostgresBridgeWorkspaceCommandRepository implements BridgeWorkspaceCommandRepository{
 private final JdbcTemplate j;public PostgresBridgeWorkspaceCommandRepository(JdbcTemplate j){this.j=j;}public void save(BridgeWorkspaceCommand v){j.update("INSERT INTO platform_bridge_workspace_commands(id,workspace_id,bridge_id,root_handle,base_ref,branch_name,worktree_key,state,created_at,completed_at) VALUES(CAST(? AS UUID),CAST(? AS UUID),CAST(? AS UUID),?,?,?,CAST(? AS UUID),?,?,?)",v.id(),v.workspaceId(),v.bridgeId(),v.rootHandle(),v.baseRef(),v.branchName(),v.worktreeKey(),v.state().name(),Timestamp.from(v.createdAt()),null);}public Optional<BridgeWorkspaceCommand> findById(String id){return j.query("SELECT * FROM platform_bridge_workspace_commands WHERE id=CAST(? AS UUID)",this::map,id).stream().findFirst();}public List<BridgeWorkspaceCommand> findPendingByBridgeId(String id){return j.query("SELECT * FROM platform_bridge_workspace_commands WHERE bridge_id=CAST(? AS UUID) AND state='PENDING' ORDER BY created_at",this::map,id);}public boolean complete(String id,BridgeWorkspaceCommandState s,Instant at){return j.update("UPDATE platform_bridge_workspace_commands SET state=?,completed_at=? WHERE id=CAST(? AS UUID) AND state='PENDING'",s.name(),Timestamp.from(at),id)==1;}private BridgeWorkspaceCommand map(ResultSet r,int n)throws SQLException{return new BridgeWorkspaceCommand(r.getString("id"),r.getString("workspace_id"),r.getString("bridge_id"),r.getString("root_handle"),r.getString("base_ref"),r.getString("branch_name"),r.getString("worktree_key"),BridgeWorkspaceCommandState.valueOf(r.getString("state")),r.getTimestamp("created_at").toInstant(),r.getTimestamp("completed_at")==null?null:r.getTimestamp("completed_at").toInstant());}}
